namespace ghidra.app.plugin.core.compositeeditor;






using docking;
using docking.action;
using docking.widgets;
using generic.theme;
using ghidra.util.exception;
using ghidra.util.exception;
using ghidra.util.task;
using ghidra.util.task;

/**
 * Action for use in the composite data type editor.
 * This action has help associated with it.
 */
public class UnpackageAction : CompositeEditorTableAction {

	private static Icon ICON = new GIcon("icon.plugin.composite.editor.unpackage");
	public static string ACTION_NAME = "Unpackage Component";
	private static string GROUP_NAME = COMPONENT_ACTION_GROUP;
	private static string DESCRIPTION = "Replace the selected composite with its components";
	private static KeyStroke KEY_STROKE = KeyStroke.getKeyStroke(KeyEvent.VK_EQUALS, 0);
	private static string[] POPUP_PATH = new string[] { ACTION_NAME };

	public UnpackageAction(StructureEditorProvider provider) : base(provider, ACTION_NAME, GROUP_NAME, POPUP_PATH, null, ICON)
    {
		setDescription(DESCRIPTION);
		setKeyBindingData(new KeyBindingData(KEY_STROKE));
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		if (!isEnabledForContext(context)) {
			return;
		}

		// If lots of components, verify the user really wants to unpackage.
		int currentRowIndex =
			model.getSelection().getFieldRange(0).getStart().getIndex().intValue();

		int subComps = model.getNumSubComponents(currentRowIndex);
		if (subComps > 1000) {
			string question = "Are you sure you want to unpackage " + subComps + " components?";
			string title = "Continue with unpackage?";
			int response =
				OptionDialog.showYesNoDialog(model.getProvider().getComponent(), title, question);
			if (response != OptionDialog.YES_OPTION) { // User did not select yes.
				return;
			}
		}

		TaskLauncher.launchModal("Unpackaging Component",
			monitor => doUnpackage(currentRowIndex, monitor));

		requestTableFocus();
	}

	private void doUnpackage(int row, TaskMonitor monitor) {
		try {
			((StructureEditorModel) model).unpackage(row, monitor);
		}
		catch (CancelledException e) {
			// user cancelled
		}
		catch (UsrException e1) {
			model.setStatus(e1.getMessage(), true);
		}
		model.fireTableDataChanged();
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		return !hasIncompleteFieldEntry() && model.isUnpackageAllowed();
	}
}
